def seed_shortlist(apps, schema_editor):
    # Use historical models so this stays compatible with Django's migration state.
    from apps.final_voting.management.commands.seed_final_ballot import SHORTLIST
    Category = apps.get_model('final_voting', 'BallotCategory')
    Division = apps.get_model('final_voting', 'BallotDivision')
    Candidate = apps.get_model('final_voting', 'Candidate')
    for order, (name, method, divisions) in enumerate(SHORTLIST, 1):
        category, _ = Category.objects.using(schema_editor.connection.alias).update_or_create(
            display_order=order, defaults={'name': name, 'method': method})
        if method == 'academic':
            continue
        for div_order, (label, names) in enumerate(divisions, 1):
            division, _ = Division.objects.using(schema_editor.connection.alias).update_or_create(
                category_id=category.pk, label=label,
                defaults={'display_order': div_order, 'required_candidates': 4})
            for position, candidate_name in enumerate(names, 1):
                Candidate.objects.using(schema_editor.connection.alias).update_or_create(
                    division_id=division.pk, position=position,
                    defaults={'name': candidate_name, 'confirmed': candidate_name != 'TO BE CONFIRMED'})


